import React, { useState, useEffect, useCallback } from 'react';
import SudokuGame, { SudokuGrid, CellValue } from './game';
import './index.css';

function SudokuPage() { // Renamed from App for clarity
  const [game, setGame] = useState<SudokuGame>(() => new SudokuGame());
  const [board, setBoard] = useState<SudokuGrid>(() => game.getBoard());
  const [initialBoard, setInitialBoard] = useState<SudokuGrid>(() => game.getInitialBoard());
  const [selectedCell, setSelectedCell] = useState<{ row: number; col: number } | null>(null);

  const updateBoardStates = useCallback(() => {
    setBoard(game.getBoard());
    setInitialBoard(game.getInitialBoard());
  }, [game]);

  useEffect(() => {
    updateBoardStates();
  }, [game, updateBoardStates]);

  const handleNewGame = (difficulty: number = 0.5) => {
    const newGame = new SudokuGame();
    newGame.generateNewPuzzle(difficulty);
    setGame(newGame);
    // updateBoardStates will be called by the useEffect hook due to 'game' changing
    setSelectedCell(null);
  };

  const handleCellClick = (row: number, col: number) => {
    if (initialBoard[row][col] === 0) { // Only allow selecting non-initial cells
      setSelectedCell({ row, col });
    } else {
      setSelectedCell(null); // Deselect if an initial cell is clicked
    }
  };

  const handleInputChange = (row: number, col: number, event: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(event.target.value, 10) as CellValue;
    if (!isNaN(value) && value >= 0 && value <= 9) { // Allow 0 to clear
      if (initialBoard[row][col] === 0) {
        game.makeMove(row, col, value);
        updateBoardStates();
      }
    }
  };
  
  const handleSolve = () => {
    game.solve(); // Solves the board in-place
    updateBoardStates(); // Updates the React state to reflect the solved board
    setSelectedCell(null); // Deselect any cell
  };

  const handleKeyPress = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (selectedCell) {
      const { row, col } = selectedCell;
      const key = parseInt(event.key);
      if (!isNaN(key) && key >= 1 && key <= 9) {
        game.makeMove(row, col, key as CellValue);
        updateBoardStates();
      } else if (event.key === 'Backspace' || event.key === 'Delete' || event.key === '0') {
        game.clearCell(row, col);
        updateBoardStates();
      }
    }
  };

  return (
    <div className="min-h-screen bg-gray-800 text-gray-100 flex flex-col items-center justify-center p-4 font-sans focus:outline-none" onKeyDown={handleKeyPress} tabIndex={0}>
      <h1 className="text-4xl font-bold text-gray-100 mb-6">Sudoku</h1>
      <div className="mb-4 flex space-x-2 justify-center">
        <button 
          onClick={() => handleNewGame(0.2)} 
          className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-lg shadow-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-75 transition-colors"
        >
          Easy
        </button>
        <button 
          onClick={() => handleNewGame(0.5)} 
          className="px-4 py-2 text-sm font-medium text-white bg-green-600 rounded-lg shadow-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-opacity-75 transition-colors"
        >
          Medium
        </button>
        <button 
          onClick={() => handleNewGame(0.8)} 
          className="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-lg shadow-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-opacity-75 transition-colors"
        >
          Hard
        </button>
      </div>
      <div className="mb-6 flex justify-center">
        <button 
          onClick={handleSolve}
          className="px-12 py-2 text-base font-medium text-purple-300 bg-transparent border-2 border-purple-400 rounded-lg shadow-sm hover:bg-purple-700 hover:text-purple-200 focus:outline-none focus:ring-2 focus:ring-purple-400 focus:ring-opacity-75 transition-colors"
        >
          Solve
        </button>
      </div>
      {/* Responsive Sudoku Board Container */}
      <div className="grid grid-cols-9 w-full max-w-[360px] aspect-square sm:max-w-[450px] sm:aspect-square md:w-[540px] md:aspect-square mx-auto border-2 border-gray-600 rounded-lg shadow-xl overflow-hidden">
        {board.map((row, rowIndex) => (
          <React.Fragment key={rowIndex}>
            {row.map((cell, colIndex) => {
              const isInitial = initialBoard[rowIndex][colIndex] !== 0;
              const isSelected = selectedCell?.row === rowIndex && selectedCell?.col === colIndex;
              const isCellCurrentlyEmpty = cell === 0;

              let cellClasses = "flex items-center justify-center border border-gray-700 text-xl md:text-2xl font-bold cursor-pointer transition-colors duration-150 ease-in-out";
              
              if (isInitial) {
                cellClasses += " bg-gray-700 text-gray-300 cursor-default";
              } else if (isSelected) {
                cellClasses += " bg-yellow-600 outline-2 outline-yellow-400 z-10 text-gray-900";
              } else {
                cellClasses += " bg-gray-800 hover:bg-gray-700 text-gray-100";
              }

              // Subgrid borders - ensuring they are slightly thicker or more prominent
              if (rowIndex % 3 === 2 && rowIndex !== 8) {
                cellClasses += " border-b-2 border-b-gray-500";
              }
              if (colIndex % 3 === 2 && colIndex !== 8) {
                cellClasses += " border-r-2 border-r-gray-500";
              }
              if (rowIndex % 3 === 0 && rowIndex !==0) { // Top border for subgrids (excluding first row of board)
                cellClasses += " border-t-2 border-t-gray-500";
              }
              if (colIndex % 3 === 0 && colIndex !==0) { // Left border for subgrids (excluding first col of board)
                cellClasses += " border-l-2 border-l-gray-500";
              }

              return (
                <div
                  key={`${rowIndex}-${colIndex}`}
                  className={cellClasses}
                  onClick={() => handleCellClick(rowIndex, colIndex)}
                >
                  {isInitial || isCellCurrentlyEmpty ? 
                    (isCellCurrentlyEmpty ? '' : cell) : 
                    (
                      <input
                        type="number"
                        min="1"
                        max="9"
                        value={cell} 
                        onChange={(e) => handleInputChange(rowIndex, colIndex, e)}
                        readOnly={false} 
                        className='w-full h-full text-center border-none text-xl md:text-2xl font-medium text-cyan-300 bg-transparent p-0 box-border focus:outline-none appearance-none m-0'
                      />
                    )
                  }
                </div>
              );
            })}
          </React.Fragment>
        ))}
      </div>
      {selectedCell && (
        <p className="mt-4 text-sm text-gray-400">Selected: Row {selectedCell.row + 1}, Col {selectedCell.col + 1}. (1-9 to enter, 0/Backspace to clear)</p>
      )}
    </div>
  );
}

export default SudokuPage; // Renamed from App for clarity
