import { Snake, Direction } from './snake';
import { FoodItem, FoodType, Position, createFoodItem, SPECIAL_FOOD_DURATION } from './food';

export interface GameState {
  boardWidth: number;
  boardHeight: number;
  snake: Position[];
  food: FoodItem[];
  score: number;
  gameOver: boolean;
  gameWon: boolean; // Can be used if there's a win condition, e.g., max score
  specialFoodTimeRemaining?: number; // Optional: seconds remaining for special food
}

export class SnakeGame {
  public boardWidth: number;
  public boardHeight: number;
  private snake: Snake;
  private foodItems: FoodItem[] = [];
  private score: number = 0;
  private isGameOver: boolean = false;
  private initialSnakePosition: Position;
  private gameLoopInterval: number | undefined;
  private specialFoodSpawnChance: number = 0.2; // This will be effectively 100% when triggered by counter
  private maxNormalFood: number = 1; // Max number of normal food items on screen
  private normalFoodsEatenSinceLastSpecial: number = 0;

  constructor(boardWidth: number = 20, boardHeight: number = 20) {
    this.boardWidth = boardWidth;
    this.boardHeight = boardHeight;
    this.initialSnakePosition = {
      x: Math.floor(boardWidth / 2),
      y: Math.floor(boardHeight / 2),
    };
    this.snake = new Snake(this.initialSnakePosition);
    this.spawnInitialFood();
  }

  private spawnInitialFood(): void {
    // Ensure at least one normal food item at the start
    this.spawnFood(false); 
  }

  private spawnFood(spawnSpecialFood: boolean): void {
    if (this.isGameOver) return;

    const currentNormalFoodCount = this.foodItems.filter(f => f.type === FoodType.NORMAL).length;

    if (spawnSpecialFood) {
      const specialFoodExists = this.foodItems.some(f => f.type === FoodType.SPECIAL);
      if (!specialFoodExists) { // Only attempt to spawn special if one doesn't exist
        const specialFood = createFoodItem(this.boardWidth, this.boardHeight, this.snake.body, this.foodItems, true);
        if (specialFood) {
          this.foodItems.push(specialFood);
        }
      }
    } else {
      // Attempt to spawn normal food
      if (currentNormalFoodCount < this.maxNormalFood) {
        const normalFood = createFoodItem(this.boardWidth, this.boardHeight, this.snake.body, this.foodItems, false);
        if (normalFood) {
          this.foodItems.push(normalFood);
        }
      }
    }
  }

  public changeDirection(direction: Direction): void {
    if (!this.isGameOver) {
      this.snake.changeDirection(direction);
    }
  }

  public update(): void {
    if (this.isGameOver) return;

    const nextPotentialHead = this.snake.getNextHeadPosition();

    if (this.isCollision(nextPotentialHead)) {
      this.isGameOver = true;
      return;
    }

    // If no collision, then move the snake
    this.snake.move(this.boardWidth, this.boardHeight);

    // Post-move logic
    this.checkFoodConsumption();
    this.cleanupExpiredFood();

    // Ensure there's always some food on the board if possible
    if (this.foodItems.length === 0) {
      this.spawnFood(false); // Default to normal food if board is empty
    }
  }

  private checkFoodConsumption(): void {
    const head = this.snake.getHeadPosition(); // After move, this is the new head
    const foodIndex = this.foodItems.findIndex(
      (food) => food.position.x === head.x && food.position.y === head.y
    );

    if (foodIndex !== -1) {
      const eatenFood = this.foodItems[foodIndex];
      this.score += eatenFood.points;
      this.foodItems.splice(foodIndex, 1);
      this.snake.grow();

      if (eatenFood.type === FoodType.NORMAL) {
        this.normalFoodsEatenSinceLastSpecial++;
        if (this.normalFoodsEatenSinceLastSpecial >= 5) {
          this.spawnFood(true); // Attempt to spawn special food
          this.normalFoodsEatenSinceLastSpecial = 0; // Reset counter
        }
      }

      // Always attempt to spawn normal food to replenish, respecting its own limits
      this.spawnFood(false);
    }
  }

  private cleanupExpiredFood(): void {
    const now = Date.now();
    this.foodItems = this.foodItems.filter(food => {
      if (food.type === FoodType.SPECIAL && food.expiresAt && food.expiresAt < now) {
        return false; // Remove expired special food
      }
      return true;
    });
  }

  private isCollision(potentialHead: Position): boolean {
    // Wall collision
    if (
      potentialHead.x < 0 ||
      potentialHead.x >= this.boardWidth ||
      potentialHead.y < 0 ||
      potentialHead.y >= this.boardHeight
    ) {
      return true;
    }

    // Self-collision (passing the potential head to the snake's method)
    if (this.snake.checkSelfCollision(potentialHead)) {
      return true;
    }
    return false;
  }

  public getGameState(): GameState {
    return {
      boardWidth: this.boardWidth,
      boardHeight: this.boardHeight,
      snake: this.snake.body.map(p => ({ ...p })), // Deep copy
      food: this.foodItems.map(f => ({ ...f, position: { ...f.position } })), // Deep copy
      score: this.score,
      gameOver: this.isGameOver,
      gameWon: false, // Implement win condition if needed
      specialFoodTimeRemaining: (() => {
        const specialFood = this.foodItems.find(f => f.type === FoodType.SPECIAL && f.expiresAt);
        if (specialFood && specialFood.expiresAt) {
          const remainingMs = specialFood.expiresAt - Date.now();
          return remainingMs > 0 ? Math.ceil(remainingMs / 1000) : 0;
        }
        return undefined;
      })(),
    };
  }

  public resetGame(): void {
    this.snake.reset(); // Snake reset now handles setting initial length and position
    this.foodItems = [];
    this.score = 0;
    this.isGameOver = false;
    this.normalFoodsEatenSinceLastSpecial = 0; // Reset counter
    this.spawnInitialFood();
  }
}
