import React, { useState, useEffect, useRef } from 'react';
import { Link, Outlet, useLocation } from 'react-router-dom';

const games = [
  { name: 'Snake', path: '/snake' },
  // { name: 'Pacman', path: '/pacman' },
  { name: 'Sudoku', path: '/sudoku' },
  { name: 'Tetris', path: '/tetris' },
  { name: 'Breakout', path: '/breakout' },
  // Add other games here as they are created
];

const GameLayout = () => {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const location = useLocation();
  // const currentGame = games.find(game => game.path === location.pathname); // No longer needed for header title
  const otherGames = games.filter(game => game.path !== location.pathname);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  return (
    <div className="min-h-screen bg-transparent text-white flex flex-col font-mono">
      <nav className="bg-gray-900 p-3 shadow-lg sticky top-0 z-50">
        <div className="container mx-auto flex flex-col sm:flex-row justify-between items-center">
          <Link 
            to="/games" 
            className="text-2xl font-bold text-purple-400 hover:text-purple-300 mb-2 sm:mb-0"
            style={{ fontFamily: '"Press Start 2P", cursive' }}
          >
            &lt; Pixel Arcade
          </Link>
          <div className="relative" ref={dropdownRef}>
            <button
              onClick={() => setIsDropdownOpen(!isDropdownOpen)}
              className="text-gray-300 hover:text-yellow-400 px-3 py-2 text-sm rounded-md transition-colors duration-200 flex items-center border border-transparent hover:border-gray-600 focus:outline-none focus:border-gray-500"
            >
              Other Games
              <svg className={`w-4 h-4 ml-1 transition-transform duration-200 ${isDropdownOpen ? 'transform rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
            </button>
            {isDropdownOpen && (
              <div className="absolute right-0 mt-2 w-48 bg-gray-800 rounded-md shadow-lg py-1 z-50 border border-gray-700">
                {otherGames.map(game => (
                  <Link
                    key={game.path}
                    to={game.path}
                    onClick={() => setIsDropdownOpen(false)} // Close dropdown on click
                    className="block px-4 py-2 text-sm text-gray-300 hover:bg-gray-700 hover:text-yellow-400 transition-colors duration-150"
                  >
                    {game.name}
                  </Link>
                ))}
              </div>
            )}
          </div>
        </div>
      </nav>
      

      <main className="flex-grow p-0 w-screen h-screen flex flex-col">
        {/* The Outlet will render the specific game component */}
        <Outlet /> 
      </main>

      <footer className="bg-gray-900 p-3 text-center text-xs text-gray-500">
        Pixel Arcade. Happy Gaming!
      </footer>
    </div>
  );
};

export default GameLayout;
