import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

interface YearData {
  year: number;
  contrib: number;
  growth: number;
  balance: number;
}

const InvestmentCalculator: React.FC = () => {
  const [years, setYears] = useState<number[]>([30000, 30000, 30000, 30000, 30000, 30000]);
  const [annualRate, setAnnualRate] = useState<number>(10);
  const [compoundFreq, setCompoundFreq] = useState<number>(1);
  const [rows, setRows] = useState<YearData[]>([]);
  const [totalInvested, setTotalInvested] = useState<number>(0);
  const [totalGrowth, setTotalGrowth] = useState<number>(0);
  const [finalValue, setFinalValue] = useState<number>(0);

  const fmt = (n: number): string => {
    return '$' + Math.round(n).toLocaleString();
  };

  const calculate = (): void => {
    const rate = annualRate / 100;
    const freq = compoundFreq;
    const ratePerPeriod = rate / freq;
    const periodsPerYear = freq;

    let balance = 0;
    const newRows: YearData[] = [];

    years.forEach((contrib, i) => {
      const startBalance = balance;
      if (freq === 1) {
        balance = (balance + contrib) * (1 + rate);
      } else {
        balance += contrib;
        for (let p = 0; p < periodsPerYear; p++) {
          balance *= (1 + ratePerPeriod);
        }
      }
      const growth = balance - startBalance - contrib;
      newRows.push({ year: i + 1, contrib, growth, balance });
    });

    const invested = years.reduce((a, b) => a + b, 0);
    const growth = balance - invested;

    setRows(newRows);
    setTotalInvested(invested);
    setTotalGrowth(growth);
    setFinalValue(balance);
  };

  useEffect(() => {
    calculate();
  }, [years, annualRate, compoundFreq]);

  const updateYear = (index: number, value: string): void => {
    const numValue = parseFloat(value);
    const updatedYears = [...years];
    updatedYears[index] = isNaN(numValue) ? 0 : numValue;
    setYears(updatedYears);
  };

  const addYear = (): void => {
    const last = years.length > 0 ? years[years.length - 1] : 30000;
    setYears([...years, last]);
  };

  const removeYear = (index: number): void => {
    if (years.length <= 1) return;
    setYears(years.filter((_, i) => i !== index));
  };

  const investedCumul = rows.map((_, i) =>
    rows.slice(0, i + 1).reduce((sum, r) => sum + r.contrib, 0)
  );

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100">
      <nav className="bg-gray-800 p-3 shadow-lg sticky top-0 z-50 border-b border-gray-700">
        <div className="container mx-auto flex justify-between items-center">
          <Link
            to="/"
            className="text-xl font-bold text-purple-400 hover:text-purple-300"
          >
            ← Back to Home
          </Link>
          <h1 className="text-white text-lg font-semibold">Investment Calculator</h1>
        </div>
      </nav>

      <div className="calc-wrap max-w-6xl mx-auto px-6 py-8">
        <div className="settings-grid">
          <div className="field">
            <label className="text-gray-300">Annual return rate (%)</label>
            <input
              type="number"
              value={annualRate}
              onChange={(e) => setAnnualRate(parseFloat(e.target.value))}
              min="0"
              max="50"
              step="0.1"
              className="w-full p-2 bg-gray-800 border border-gray-600 rounded text-white"
            />
          </div>
          <div className="field">
            <label className="text-gray-300">Compound frequency</label>
            <select
              value={compoundFreq}
              onChange={(e) => setCompoundFreq(parseInt(e.target.value))}
              className="w-full p-2 bg-gray-800 border border-gray-600 rounded text-white"
            >
              <option value="1">Annually</option>
              <option value="12">Monthly</option>
              <option value="4">Quarterly</option>
            </select>
          </div>
        </div>

        <p className="section-label text-sm font-semibold text-gray-400 mb-2">Yearly contributions</p>
        <div id="years-list">
          {years.map((value, i) => (
            <div key={i} className="year-row mb-2">
              <span className="year-tag text-sm text-gray-400">Yr {i + 1}</span>
              <input
                type="range"
                min="0"
                max="200000"
                step="500"
                value={value}
                onChange={(e) => updateYear(i, e.target.value)}
                className="w-full"
              />
              <span className="year-val text-sm font-medium text-gray-200">{fmt(value)}</span>
              <button
                onClick={() => removeYear(i)}
                className="remove-btn hover:bg-gray-800 text-gray-400 hover:text-red-400"
                title="Remove year"
              >
                ✕
              </button>
            </div>
          ))}
        </div>

        <div className="flex gap-2 mb-6">
          <button
            onClick={addYear}
            className="add-btn bg-purple-600 text-white px-4 py-2 rounded hover:bg-purple-500 text-sm"
          >
            + add year
          </button>
        </div>

        <hr className="divider border-t border-gray-700 my-5" />

        <div className="metric-grid">
          <div className="metric bg-gray-800 p-4 rounded border border-gray-700">
            <p className="metric-label text-xs text-gray-400 mb-1">Total invested</p>
            <p className="metric-value text-xl font-semibold text-gray-100">{fmt(totalInvested)}</p>
          </div>
          <div className="metric bg-gray-800 p-4 rounded border border-gray-700">
            <p className="metric-label text-xs text-gray-400 mb-1">Total growth</p>
            <p className="metric-value text-xl font-semibold text-green-400">{fmt(totalGrowth)}</p>
          </div>
          <div className="metric bg-gray-800 p-4 rounded border border-gray-700">
            <p className="metric-label text-xs text-gray-400 mb-1">Final value</p>
            <p className="metric-value text-xl font-semibold text-gray-100">{fmt(finalValue)}</p>
          </div>
        </div>

        <div className="legend flex gap-4 text-sm text-gray-400 mb-2">
          <span className="flex items-center gap-1">
            <span className="leg-sq bg-gray-600 border border-gray-500"></span>
            Invested
          </span>
          <span className="flex items-center gap-1">
            <span className="leg-sq bg-green-500"></span>
            Growth
          </span>
        </div>

        <div className="chart-row flex gap-1 items-end h-32 my-4">
          {rows.map((row, i) => {
            const maxBal = finalValue || 1;
            const maxH = 110;
            const invH = Math.round((investedCumul[i] / maxBal) * maxH);
            const growH = Math.max(0, Math.round((row.balance / maxBal) * maxH) - invH);

            return (
              <div key={i} className="chart-col flex-1 flex flex-col items-center gap-1 h-full justify-end">
                <div className="chart-bar-wrap w-full flex-1 flex flex-col justify-end">
                  <div
                    className="chart-bar-growth bg-green-500 w-full"
                    style={{ height: `${growH}px` }}
                  ></div>
                  <div
                    className="chart-bar-invested bg-gray-600 border border-gray-500 w-full"
                    style={{ height: `${invH}px` }}
                  ></div>
                </div>
                <span className="chart-xlabel text-xs text-gray-400">Y{row.year}</span>
              </div>
            );
          })}
        </div>

        <hr className="divider border-t border-gray-700 my-5" />

        <p className="section-label text-sm font-semibold text-gray-400 mb-2">Year-by-year breakdown</p>
        <div className="table-wrap overflow-x-auto">
          <table className="w-full text-sm bg-gray-800 border border-gray-700 rounded">
            <thead>
              <tr className="bg-gray-700">
                <th className="text-left text-xs text-gray-300 uppercase border-b border-gray-600 p-2">Year</th>
                <th className="text-right text-xs text-gray-300 uppercase border-b border-gray-600 p-2">Contribution</th>
                <th className="text-right text-xs text-gray-300 uppercase border-b border-gray-600 p-2">Growth</th>
                <th className="text-right text-xs text-gray-300 uppercase border-b border-gray-600 p-2">End balance</th>
                <th className="border-b border-gray-600 p-2 text-gray-300" style={{ width: '80px' }}>Progress</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.year} className="hover:bg-gray-700">
                  <td className="p-2 border-b border-gray-700 text-gray-200">{row.year}</td>
                  <td className="p-2 border-b border-gray-700 text-right text-gray-200">{fmt(row.contrib)}</td>
                  <td className="p-2 border-b border-gray-700 text-right text-green-400">{fmt(row.growth)}</td>
                  <td className="p-2 border-b border-gray-700 text-right text-gray-200">{fmt(row.balance)}</td>
                  <td className="p-2 border-b border-gray-700">
                    <div className="bar-bg bg-gray-600 h-1 rounded overflow-hidden">
                      <div
                        className="bar-fill bg-green-500 h-full"
                        style={{ width: `${Math.round((row.balance / (finalValue || 1)) * 100)}%` }}
                      ></div>
                    </div>
                  </td>
                </tr>
              ))}
              {rows.length > 0 && (
                <tr className="bg-gray-700 font-semibold">
                  <td className="p-2 border-b-0 text-gray-100">Total</td>
                  <td className="p-2 border-b-0 text-right text-gray-100">{fmt(totalInvested)}</td>
                  <td className="p-2 border-b-0 text-right text-green-400">{fmt(totalGrowth)}</td>
                  <td className="p-2 border-b-0 text-right text-gray-100">{fmt(finalValue)}</td>
                  <td className="p-2 border-b-0"></td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <style>{`
        .calc-wrap {
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
          padding: 1.5rem 0;
        }
        .section-label {
          font-size: 12px;
          font-weight: 500;
          color: #9ca3af;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          margin: 0 0 10px;
        }
        .year-row {
          display: grid;
          grid-template-columns: 56px 1fr 80px 28px;
          gap: 8px;
          align-items: center;
          margin-bottom: 6px;
        }
        .year-tag {
          font-size: 13px;
          color: #9ca3af;
        }
        .year-val {
          font-size: 13px;
          font-weight: 500;
          color: #f3f4f6;
          text-align: right;
        }
        .remove-btn {
          background: none;
          border: none;
          cursor: pointer;
          font-size: 14px;
          color: #6b7280;
          width: 28px;
          height: 28px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 4px;
        }
        .remove-btn:hover {
          background: #1f2937;
          color: #f87171;
        }
        .add-btn {
          background: none;
          border: 1px solid #4b5563;
          border-radius: 6px;
          width: 28px;
          height: 28px;
          cursor: pointer;
          font-size: 16px;
          color: #6b7280;
          display: flex;
          align-items: center;
          justify-content: center;
        }
        .add-btn:hover {
          background: #1f2937;
        }
        .metric-grid {
          display: grid;
          grid-template-columns: repeat(3, minmax(0, 1fr));
          gap: 10px;
          margin: 1.5rem 0;
        }
        .metric {
          background: #1f2937;
          border-radius: 8px;
          padding: 14px;
        }
        .metric-label {
          font-size: 12px;
          color: #9ca3af;
          margin: 0 0 4px;
        }
        .metric-value {
          font-size: 20px;
          font-weight: 500;
          color: #f3f4f6;
          margin: 0;
        }
        .legend {
          display: flex;
          gap: 16px;
          font-size: 12px;
          color: #9ca3af;
          margin-bottom: 8px;
        }
        .legend span {
          display: flex;
          align-items: center;
          gap: 5px;
        }
        .leg-sq {
          width: 10px;
          height: 10px;
          border-radius: 2px;
        }
        .chart-row {
          display: flex;
          gap: 6px;
          align-items: flex-end;
          height: 120px;
          margin: 1rem 0;
        }
        .chart-col {
          flex: 1;
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 2px;
          height: 100%;
          justify-content: flex-end;
        }
        .chart-bar-wrap {
          width: 100%;
          flex: 1;
          display: flex;
          flex-direction: column;
          justify-content: flex-end;
        }
        .chart-bar-invested {
          background: #374151;
          border: 1px solid #4b5563;
          border-radius: 3px 3px 0 0;
          width: 100%;
        }
        .chart-bar-growth {
          background: #10b981;
          border-radius: 3px 3px 0 0;
          width: 100%;
        }
        .chart-xlabel {
          font-size: 10px;
          color: #6b7280;
        }
        .settings-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 12px;
          margin-bottom: 1.25rem;
        }
        .field label {
          display: block;
          font-size: 12px;
          color: #9ca3af;
          margin-bottom: 4px;
        }
        input[type="number"], select {
          width: 100%;
          padding: 8px;
          border: 1px solid #4b5563;
          border-radius: 4px;
          background: #1f2937;
          color: #f3f4f6;
        }
        .bar-bg {
          height: 6px;
          background: #4b5563;
          border-radius: 3px;
          overflow: hidden;
          margin-top: 2px;
        }
        .bar-fill {
          height: 100%;
          border-radius: 3px;
          background: #10b981;
          transition: width 0.3s;
        }
      `}</style>
    </div>
  );
};

export default InvestmentCalculator;